INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот дар бораи имҳои зарароварон ва бемориҳои шӯла</h2>\n<p>Ҷиҳати ҳуҷури бӯъ ва бӯи хуб ва қимати озуавии баланд, сафрави сафрав (Saturex hortense) дар байни инсонихон ва кӯлопҳои хонагӣ хеле маъмул аст. Аммо, кишти ин ҷунки дар рӯи имҳохое намоён аст, ки аз ҷумлаи онҳо <strong>Зарароварон ва бемориҳои шӯла</strong> ҳастанд. Бисёри кӯлопхо фикр мекунанд, ки имҳои зарароварон талаботи баҳои зерҳаст, аммо маълумоти майдонагӣ нишон медиҳад, ки қисми зиёди ин мушкилот дар рафторҳои нодурусти обкунӣ, бахусус обкунии қадимагонӣ реша доранд. Дар ин услуби нав,  <a href="https://navar-abyari.ir/obyorii-juyaki/">обкунии қадимагонӣ</a> одиҳо сабабгори пайдои шароити раҳоии мунтазами ҷойҳои кучук ва баргҳо мешавад, ки ин раванд суръати паҳншавии зангҳои хокӣ ва кабудҳоро ба таври назаррас зиёд мекунад. Бинобар ин, тағйири парадигм аз обкунии умумӣ ба обкунии маҳаллӣ қадамҳои аввалин барои имҳои биологӣ ва химиявии самараноктар ҳисоб мекунад.</p>\n\n<h2>Таъсири мустақими обкунии қатрагӣ ба кам кардани пайдои бемориҳо</h2>\n<p>Яке аз фарқияти бунёдӣ дар имҳои кишоварзӣ, шакли паҳншавии раҳоӣ аст. Дар системаҳои обкунии қатрагӣ, об ба таври қатрақатра ва мустақиман ба минтақаи решаҳо (Root Zone) дода мешавад. Ин раванд аз ду нигарши барои мубориза бо <strong>зарароварон ва бемориҳои шӯла бо обкунии қатрагӣ</strong> бисёр муҳим аст. Якум, камшавии раҳоии нисбии рӯи барг ва хок. Бисёри патогенҳои зангӣи шӯла, баъд аз Alternaria ва Botrytis, барои пайдошавӣ ва ворид шудан ба бофтаи ҷунки ба раҳоии баланди рӯӣ эҳтиёҷ доранд. Бо нигоҳ доштан хушкии нисбии сатҳи замин ва баргҳо, моҳи вақти барои инкубатсияи бемориҳо кам мешавад. Дуюм, зиёдшавии қобилияти муборизаи ҷунки. Ҷункҳое, ки зери стресси раҳоии камтар ҳастанд, сарчашмаҳои энергияи худро барои рушди афшӣ ва мустаҳкам кардани сохтори худкунӣ истифода мекунанд, на танҳо истеҳсоли тӯҷав барои ҷубронии стресс ё мубориза бо заҳриҳои иктисобӣ. Дар ин ҳама, фаҳмиш чархаҳои зиндагии патогенҳо ва алоқамандии онҳо бо ҳарорати хок зарур аст. Шумо метавонед бо омӯзиши <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D8%AD%D9%84%D8%A8%DA%86%D9%87/">шароити обкунӣ бо танзими қатрагӣ дар хонаи баланд</a>， ба микромуҳити маҳаллӣ назорати дақиқтар дошта бошед.</p>\n\n[{{[IMAGE_1]}}]\n\n<h2>Имҳои зарароварони ҳашаротӣ бо бандҳои титиб</h2>\n<p>Бисёри зарароварони ҳашаротии шӯла, баъд аз ҳашароти хонак, хункуши баргҳо ва ҳашароти сафед, ба раҳоии баланди ҷункҳо ҳассосияти баланд доранд ё дар муҳити раҳоии суръати зиндамонӣ баландтарро иҷроиш мекунанд. Обкунии қатрагӣ бо кам будани паҳншавии раҳоӣ дар фазои байнисири, хонаи бисёри ин зарароваронро душвор мекунад. Гиреҳ, ин система имконияти истифодаи аз худ кардани озуавӣ ва заҳрпашкунӣ (Fertigation ва Pestigation) -ро фароҳам меорад. Ин маънои онро дорад, ки шумо метавонед дар вақти муайян, маҳлулҳои зангкушӣ ё ҳашароткушро мустақиман ба решаҳо ё тавари хӯрокхӯрӣ ба ҷунки брасед, бе он ки бо ҳамдигар таъсири ғайридодӣ кунанд ё раҳоии сатҳиро зиёд кунанд. Барои беҳтар кардани ин раванд, интихоби қатракушони мувофиқ бо сардҳои дуруст аҳамияти хос дорад. Мо тавсия мекунем, ки барои фаҳмиши беҳтари моҳҳои вақти обкунӣ, дараҷаи обкунакии банди титибро бо шароити иқлимии минтақаи худ танзим кунед. Танзимҳои беҳтарин, на танҳо сабабгори камшавии истифодабарии об, балки барои солимболии ҷунки вобаста ба фишорҳои биологӣ боиси инкишоф мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-شاهی-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های شاهی با آبیاری قطره‌ای - تصویر 1"/><figcaption>zararovaron bemori obkuniii qatragi shuli</figcaption></figure>\n\n<h2>Имҳои зарароварон ва бемориҳои шӯла</h2>\n<p>Барои истифодабарии комилтарини фоидаҳои ин услуб дар мубориза бо <strong>зарароварон ва бемориҳои шӯла</strong>аммо рӯйхати зеро тавсия мешавад:</p>\n<ul>\n<li><strong>аз оварии охирин ба сатҳи замин парhez кунед:</strong> ҳатман аз системаҳои тамзилии линиявӣ ё нуқтагӣ истифода баред, ки обро дар чуқурии 10 то 15 сантиметр мавҷуд мекунанд, то намӣ ба сатҳи замин баргардад.</li>\n<li><strong>замонакунӣ оварӣ:</strong> беҳтар аст, ки оварӣ дар соатҳои охири шом ё ибтидои шаб анҷом дода шавад, то имконияти хушк шудани баргҳо дар тӯли шаб ва кам шудани фаъолияти зараррасонҳо вуҷуд дошта бошад.</li>\n<li><strong>идоракунии кал ва намӣ:</strong> пайгирии доимии намии замин дар қисми решаи гиёҳ. Агар намӣ зиёд бошад, ҳатто дар системаи тамзиливӣ ҳам, фосилаи байни оварииҳо бояд зиёд карда шавад, то сохтори замин ҳавои кофӣ барои нафаскашӣ реша ва муқовимат ба бемориҳои бактериявиро дошта бошад.</li>\n<li><strong>истифода аз чорпӯшҳои намӯштанда:</strong> дар паҳлуи системаи тамзиливӣ, истифодаи чорпӯшҳои растании (монанди канна ё чӯбҳои хушк) барои идоракунии ордук ва кам кардани бухоршавии об метавонад як ноқили физикӣ барои воридшавии зараррасонҳои заминӣ бошад.</li>\n</ul>\n<p>Илова бар ин, хуруфгардонии кӯштор ва чархзанонии гиёҳҳо нақши асосӣ дорад. Гиёҳҳои шеви на бояд дар наздикии гиёҳҳои сифатноки бемориҳои қарачашонаи монанди шуда кардан шаванд. Инчунин, интихоби тоҳук дар сифати баланд ва бе зараррасон аз марҳилаи партобидан, хатари воридшавии бемориҳои системӣ-ро ба ҳадди ақал мерасонад. Дар ин самт, омӯзиши манбаъҳои маъруф дар бораи зичии кӯштҳои дигар гиёҳҳо метавонад диди ҷамъи-тари барои идоракунии кишоварзӣ эҷод кунад; масалан, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%a8%d8%a7%d9%82%d9%84%d8%a7-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори тоҳук баққала дар гектар + омилҳои таъсиррасон ба самаранокии</a> муҳимияти мувозинат будани зичӣ ва фосилагузорӣ барои салубатди муносиб нишон медиҳад.</p>\n\n[{{[IMAGE_2]}}]\n\n<h2>пешгири аз банд омадан ва нигоҳдории солимни системаи оварӣ</h2>\n<p>яке аз мушкилоти маъмул дар истифодаи системаҳои тамзиливӣ, банд омадани системаи тамзиливӣ бо сабаби ғоззҳо ё рушди биологӣ дар дохили лӯлаҳо мебошад. Ин масъала бевосита бо салубатди гиёҳ робита дорад. Агар филтрҳо дуруст нигоҳ дошта нашаванд, патогенҳое дар об метавонанд бевосита ба решаи шеви ворид шуда, бемориҳои сиёҳшавии реша ё ғилхӯрӣ-ро даранд кунанд. Бинобар ин, барқарорсозӣ ва ивазкунии давравии филтрҳо ва шустан бо хлор ё кислотаи лимонӣ, қисме аз протоколи санитарӣ мебошад. Илова бар ин, нигоҳдории дурусти таҷҳизот, умри кории системаро зиёд карда, хароҷоти пинҳони истеҳсолро коҳиш медиҳад. Дар ин чорчӯба, шинос шудан ба <a href="https://navar-abyari.ir/%d9%86%da%af%d9%87%d8%af%d8%a7%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%88-%d9%87%d8%b2%db%8c%d9%86%d9%87/">нигоҳдории системаи тамзиливӣ ва хароҷотҳо</a> зарур аст, то метавонед аз паст шудани сифати коркунии система парhez кунед. Системаи тамзиливии солим, тақсимоти якхелаи обро таъмин мекунад ва аз стресси пайвастаи реша пешгирӣ менамояд; стрesse, ки заминаи ҳароспазории гиёҳ нисбати зараррасонҳоро месозад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-شاهی-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های شاهی با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation шеви</figcaption></figure>\n\n<h2>ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<h3>Оя напойка тамғазида метавонад ҷойи тамоми баҳшпашӣҳоро иваз кунад?</h3>\n<p>Не, напойка тамғазида василоти идоракунӣ аст, на даво. Ин система бемориҳоро кам мекунад, аммо агар равшаниҳо пеш аз ҳама сироят шуда бошанд, эҳтиёҷ ба баҳшпашии дақиқ шуда метавонад ба вуҷуд ояд. Муштараф кардани напойкаи тамғазида бо паҳнокунии хӯроки, беҳтарин стратегии ҳастанд.</p>\n<h3>Дар кадом марҳилаи рӯиидуни раг, идоракунии зараррасонҳо бо тамғазида муассартар аст?</h3>\n<p>Аз марҳилаи интиқоли наҳол то охирин даври мевагӣ. Дар марҳилаҳои ибтидоӣ, заиф будани решаҳо равшаниҳоро аз бемориҳои реша ҳассос мекунад. Напойкаи дақиқ аз рӯзи аввал ба мустаҳкам шудани решаҳои солим мусоидат мекунад, ки дастурзистони муқовимати қавитарро нисбати зараррасонҳо бардошта мегардонанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-شاهی-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های شاهی با آبیاری قطره‌ای - تصویر 3"/><figcaption> зараррасониҳои рағҳо бемориҳо напойка тамғазида рағҳ</figcaption></figure>\n<h3>Оя хароҷоти ибтидоии насби тамғазида барои ҷаннати рағҳ истифодабаранда аст?</h3>\n<p>Бале, бо назардошти кам шудани истифодабарии об, кам шудани вайроншавӣ аз сабаби бемориҳо ва зиёд шудани андозаи ғунт доруи рашони рашони рағҳ, сармоягузории ибтидоӣ дар системаҳои напойкаи тамғазида одатан дар 1 то 2 фасл барқарор мешавад. Илова бар ин, истеъдоди баландтар дар ҷаннатҳои зичкунанда, фоидавиро ду баробар мегардонад. Барои муқоисаи самаранокӣ, шумо метавонед <a href="https://navar-abyari.ir/vegetable-yield-per-hectare-guide/">Роҳнамои истеҳсоли сабзаҷотӣ дар гектар</a> ро оварда мазкур кунед, то потенсиали воқеии рағҳ дар шароити идеалӣро донед.</p>\n\n[{{[IMAGE_3]}}]\n\n<h2>Хулоса</h2>\n<p>Идоракунӣ <strong>Зараррасониҳо ва бемориҳои рағҳ</strong> як раванди чандсатҳа аст, ки дар он интихоби усули напойка нақши марказӣ мебозад. Напойкаи тамғазида бо кам шудани намии сатҳӣ, беҳтар кардани ҷамъияти решаҳо ва имконияти баҳшпашии дақиқ, асосҳои асосии истеҳсоли доимӣ ва солимро ташкил медиҳад. Бо назардошти ҳассосияти раёни рағҳ ба омилҳои иқлимию биологӣ, гузариш аз усулҳои анъанавӣ ба напойкаи тамғазида, на танҳо интихоти иқтисодӣ, балки зарурати бемазӯ барои ҳифзи сифати маҳсулот аст. Тавсия дода мешавад, ки ҷаннати паҳлӯи ҷаннатҳои дигар, монанди кунҳои равғанӣ низ бо диққат баҳодиҳӣ шуда бошад; ба сифила намуна, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%aa%d8%b1%db%8c%d8%aa%db%8c%da%a9%d8%a7%d9%84%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Микдори бадироти трикатика дар гектар + Ҷадвали зичии ҷаннат</a> намоён аст, ки чӣ тавр барномарезии фазоӣ дар майдон амал мекунад, то мубориза барои захираҳо ва паҳн шудани зараррасониҳо байни маҳсулоти рағҳ пешгириӣ карда шавад. Дар ниҳоӣ, пайгирии муътадил, назорати намӣ ва нигоҳдории системаҳо, калиди муваффақият дар ин роҳ аст.</p>','Муборизи бо ҳарос ва бемориҳои шаҳӣ бо истифодаи обёрӣи қатрагӣ','Абории қатқата на танҳо сарфаи обро кам мекунад, балки бо кам шудани намнокии рӯи ҷисми растани, муҳити афзоиши патогенҳои зангӯбӣ ва зараррасонҳоро маҳв мекунад. Дар ин мақола чораҳои амалии идоракунии бемориҳо ва зараррасонҳои шаҳӣ бо технологияи навъи паллӣ муҳоким шудаанд.','publish','closed','closed','muborizi-va-bemorih-i-shahi-bo-abiyr-i-qatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
